const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['沒有備案可以用志工嗎','不予經費補助'],['忘記送志工計畫備案會怎樣','第7條'],['我們沒報備志工可以嗎','備案'],
['我們協會想招志工要先做什麼','公告'],['想召募志工要怎麼做','第6條'],
['志工計畫書要寫什麼','考核'],['志願服務計畫要包括什麼內容','召募、訓練'],
['協會要幫志工辦志工證嗎','第2條'],['志工證一定要辦嗎','服務證'],
['志工可以免費進風景區嗎','榮譽卡'],['志工進景點有沒有門票優待','300小時'],['志工有證照才能做的事怎麼辦','第13條'],
['志工訓練要上幾小時','沒有寫幾小時'],['基礎訓練在哪裡上','衛生福利部'],
['志工要督導嗎誰督導','專人'],['義工跟志工一樣嗎','第3條'],['志工的名冊要送縣府嗎','資訊整合系統'],['志工資料要交給縣府嗎','資訊整合系統'],
['志工是會員嗎要繳會費嗎','不同的身分'],['志工隊要不要另外立案','不用另外立案'],['志工不小心弄壞別人東西誰賠','第22條'],
['協會要用志工需不需要先報縣府','第7條'],['志工計畫沒送會怎樣','不予經費補助'],['志工招募前要不要公告','第6條'],['志工做錯事被告誰要負責','第22條'],['志工是不是員工','不以獲取報酬'],['協會志工要多少人才能成立','沒有規定'],['志工隊可以跨協會嗎','聯合'],['志工誰在管','專人'],['志工要上哪些課在哪裡報名','衛生福利部']];
const no=['合作社志工沒有備案可以嗎','志工證誰發','志工受傷誰負責','志工要不要保意外險','志工做滿幾小時可以拿榮譽卡','解散後要做什麼清算','理事長失聯要解散怎麼辦','協會要不要幫員工保勞保','志工可以領車馬費嗎','協會會費要繳多少'];
const mine=/^(志工沒有先備案|協會想招志工|志願服務計畫要寫|協會要幫志工辦志工證|志工進風景區|要專門執業證照|志工訓練的時數|志工要有人督導|義工和志工|志工名冊不是|志工和會員不同|志工隊不用|運用志工前要先備案|召募志工時要公告|志工不是領薪水的員工|志工隊要幾個人|志工跨單位|志工服務時弄壞)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const x=a&&a.title?(a.title+a.summary):'';if(!x.includes(e)||!a.direct||!mine.test(a.title)){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
